func encQuestion(out []byte, v *Question, depth int) []byte {
	out = append(out, '{')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "asker")
	out = append(out, ':', ' ')
	out = esc(out, v.Asker)
	out = append(out, ',')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "key")
	out = append(out, ':', ' ')
	out = esc(out, v.Key)
	if len(v.Slots) != 0 {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "slots")
		out = append(out, ':', ' ')
		out = strmap(out, v.Slots, depth+1)
	}
	out = append(out, '\n')
	out = pad(out, depth)
	return append(out, '}')
}

func encRequest(out []byte, v *Request, depth int) []byte {
	out = append(out, '{')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "op")
	out = append(out, ':', ' ')
	out = esc(out, v.Op)
	if v.Ask != nil {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "ask")
		out = append(out, ':', ' ')
		out = encQuestion(out, v.Ask, depth+1)
	}
	if v.Wait {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "wait")
		out = append(out, ':', ' ')
		if v.Wait {
			out = append(out, 't', 'r', 'u', 'e')
		} else {
			out = append(out, 'f', 'a', 'l', 's', 'e')
		}
	}
	if v.ID != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "id")
		out = append(out, ':', ' ')
		out = esc(out, v.ID)
	}
	if v.Option != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "option")
		out = append(out, ':', ' ')
		out = esc(out, v.Option)
	}
	if v.Admin != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "admin")
		out = append(out, ':', ' ')
		out = esc(out, v.Admin)
	}
	out = append(out, '\n')
	out = pad(out, depth)
	return append(out, '}')
}

